/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void can_v_usr_err_add (Can_V_Usr_Error_Code code, Can_Dev_Id dev_id)
{  
  can_v_usr_err.log.ptr %= CAN_V_USR_ERR_BUFF_SIZE ;
  
  can_v_usr_err.log.code[can_v_usr_err.log.ptr++] = (Can_V_Usr_Error_Code)(code | (dev_id << CAN_V_USR_DEV1_BIT)) ;

  if(can_v_usr_err.count[code-1] != 0xFF)
    {
	  can_v_usr_err.count[code-1]++ ;
    }
  //
		can_do_err_save = TRUE;
		//can_v_usr_err_save () ;
}

